INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(12301, 'Job 18:13', 'Job', 18, 13, '&nbsp;بيمارى د هغوئ څرمن خورى، او مرګ د هغوئ اندامونه خورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12302, 'Job 18:14', 'Job', 18, 14, '&nbsp;چې په کومو خېمو کښې هغوئ په حِفاظت کښې وُو نو هغوئ ويستلے شوى دى، او هغوئ د دهشت بادشاه ته راوستلے شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12303, 'Job 18:15', 'Job', 18, 15, '&nbsp;د هغوئ په خېمو کښې هيڅ څوک هم پاتې نۀ دى، او د هغوئ د کورونو دپاسه د ګوګړو باران دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12304, 'Job 18:16', 'Job', 18, 16, '&nbsp;د هغوئ جرړې لاندې اوچې شوې دى، او د هغوئ څانګې پاس مړاوې شوې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12305, 'Job 18:17', 'Job', 18, 17, '&nbsp;د هغوئ نوم به د زمکې نه ختم شى، او په لارو کوڅو کښې به د هغوئ ذکر نۀ کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12306, 'Job 18:18', 'Job', 18, 18, '&nbsp;هغوئ د رڼا نه تيارې ته ديکه کړے شوى دى، او د دُنيا نه شړلے شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12307, 'Job 18:19', 'Job', 18, 19, '&nbsp;د هغوئ اولاد نشته، او د هغوئ د خاندان يو کس هم ژوندے پاتې شوے نۀ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12308, 'Job 18:20', 'Job', 18, 20, '&nbsp;د نمرخاتۀ طرف نه واخله تر نمرپرېواتۀ پورې چې څوک هم د هغوئ د اَنجام نه خبريږى، نو د يرې نه لړزيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12309, 'Job 18:21', 'Job', 18, 21, '&nbsp;دوئ به وائى چې دا د بدعمله خلقو کور دے، د هغه چا څوک چې د خُدائ پاک نه منکر وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12310, 'Job 19:1', 'Job', 19, 1, '&nbsp;بيا ايُوب جواب ورکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12311, 'Job 19:2', 'Job', 19, 2, '&nbsp;”تۀ به تر کومې پورې ما له تکليف راکوې، او په خپلو خبرو به زما زړۀ غوڅوې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12312, 'Job 19:3', 'Job', 19, 3, '&nbsp;تا لس ځلې زما بې‌عزتى کړې ده، تۀ چې ما له کوم تکليف راکوې په هغې تۀ شرمېږې نۀ څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12313, 'Job 19:4', 'Job', 19, 4, '&nbsp;او کۀ دا رښتيا هم وى چې ما غلطى کړې ده، نو ستا په کښې څۀ کار دے؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12314, 'Job 19:5', 'Job', 19, 5, '&nbsp;تۀ په خپل نظر کښې زما نه لوئ يې، زما تکليف د ګناه د ثبوت دپاره استعمالوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12315, 'Job 19:6', 'Job', 19, 6, '&nbsp;نو بيا پوهه شه چې خُدائ پاک زۀ په غلطه کړے يم، او زما نه ګېرچاپېره يې جال خور کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12316, 'Job 19:7', 'Job', 19, 7, '&nbsp;ګوره، زۀ د فرياد چغې هم وهم، خو څوک ما له جواب نۀ شى راکولے، زۀ په زوره زوره چغې وهم، خو اِنصاف نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12317, 'Job 19:8', 'Job', 19, 8, '&nbsp;خُدائ پاک زما لارې بندې کړې دى او زۀ خوځېدے نۀ شم، او هغۀ زما په لار کښې تيارې جوړې کړې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12318, 'Job 19:9', 'Job', 19, 9, '&nbsp;هغۀ زما نه عزت اخستے دے، او زما د سر نه يې تاج اخوا کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12319, 'Job 19:10', 'Job', 19, 10, '&nbsp;هغه د هر طرف نه ما راغورزوى او زۀ ختم يم، هغۀ د ونې په شان زما د اُميد جرړې راويستلې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12320, 'Job 19:11', 'Job', 19, 11, '&nbsp;هغه زما خِلاف سخت غصه شوے دے، او هغه مې خپل دشمن ګڼى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12321, 'Job 19:12', 'Job', 19, 12, '&nbsp;د هغۀ فوجيان راغونډ شوى دى، هغوئ په ما باندې حملې دپاره لارې تيارې کړې دى. او زما د خېمې نه ګېرچاپېره يې خېمې لګولې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12322, 'Job 19:13', 'Job', 19, 13, '&nbsp;زما خپلوان ما نه ځان لرې ساتى، او زما دوستان زما خلاف شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12323, 'Job 19:14', 'Job', 19, 14, '&nbsp;زما خپلوانو او زما نزدې دوستانو زۀ پرېښے او هېر کړے يم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12324, 'Job 19:15', 'Job', 19, 15, '&nbsp;زما په کور کښې مېلمنو زۀ هېر کړے يم، زما وينځې ما پردے سړے ګڼى، زۀ د هغوئ په نظر کښې يو مسافر يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12325, 'Job 19:16', 'Job', 19, 16, '&nbsp;زۀ چې خپل نوکر راوغواړم نو هغه ما له نۀ راځى، زۀ هغۀ ته سوال زارى کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12326, 'Job 19:17', 'Job', 19, 17, '&nbsp;زما د خولې بوئ هم زما په ښځه باندې بد لګى، زما خپل خاندان زما نه نفرت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12327, 'Job 19:18', 'Job', 19, 18, '&nbsp;واړۀ ماشومان هم ما ته سپک ګورى، کله چې زۀ هغوئ سره خبرې کول غواړم نو هغوئ ما ته شا کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12328, 'Job 19:19', 'Job', 19, 19, '&nbsp;زما نزدې ملګرى زما نه نفرت کوى، او چې د چا سره ما مينه کوله نو هغوئ زما نه مخ اړولے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12329, 'Job 19:20', 'Job', 19, 20, '&nbsp;په ما کښې صرف هډوکى او څرمن پاتې دى او ډېر په مشکله د مرګ نه تښتېدلے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12330, 'Job 19:21', 'Job', 19, 21, '&nbsp;اے زما دوستانو، په ما باندې رحم وکړئ، په ما باندې رحم وکړئ، ځکه چې د خُدائ پاک ګزار زۀ وهلے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12331, 'Job 19:22', 'Job', 19, 22, '&nbsp;تاسو د خُدائ پاک په شان ولې ما پسې يئ، تاسو زۀ ښۀ نۀ يم کړولے څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12332, 'Job 19:23', 'Job', 19, 23, '&nbsp;کاش چې زما خبرې ليکلے شوے وے، کاش چې زما خبرې په يو کِتاب کښې بيان شوے وے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12333, 'Job 19:24', 'Job', 19, 24, '&nbsp;کاش چې د اوسپنې او د پيتلو د قلم سره دا خبرې په يو ګټ باندې د تل دپاره نقش شوے وے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12334, 'Job 19:25', 'Job', 19, 25, '&nbsp;زما يقين دے چې زما خلاصونکے ژوندے دے، او چې په آخر کښې به هغه د زمکې دپاسه ودريږى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12335, 'Job 19:26', 'Job', 19, 26, '&nbsp;او چې کله زما څرمن بلکل ختمه شى، نو بيا به زۀ په خپلو سترګو خُدائ پاک ووينم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12336, 'Job 19:27', 'Job', 19, 27, '&nbsp;زۀ به هغه په خپله وګورم، او زۀ به هغه په خپلو سترګو ووينم. ما سره صرف هم دغه فکر دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12337, 'Job 19:28', 'Job', 19, 28, '&nbsp;ستا حق نۀ جوړيږى چې ما له تکليف راکوې، او وائې چې دا ستا خپله غلطى ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12338, 'Job 19:29', 'Job', 19, 29, '&nbsp;د سزا نه پخپله يرېږه ځکه چې ستا رويه د سزا لائقه ده، او بيا به تا ته پته ولګى چې حساب کِتاب شته.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12339, 'Job 20:1', 'Job', 20, 1, '&nbsp;بيا ضوفر نعماتى ورته ووئيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12340, 'Job 20:2', 'Job', 20, 2, '&nbsp;”زما زړۀ وائى چې جواب درکړم، ځکه چې ستا خبرو زۀ خفه کړے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12341, 'Job 20:3', 'Job', 20, 3, '&nbsp;تا چې څۀ وفرمائيل هغه زما بې‌عزتى ده، او زما زړۀ ما ته وائى چې جواب درکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12342, 'Job 20:4', 'Job', 20, 4, '&nbsp;تا ته د ډېر وخت نه د دې پته ده، د هغه وخت نه چې کله بنى آدم په زمکه پېدا شوے وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12343, 'Job 20:5', 'Job', 20, 5, '&nbsp;د بدعمله کس کاميابى لنډه وى، او د خُدائ پاک نه منکرو خلقو خوشحالى د لږ وخت دپاره وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12344, 'Job 20:6', 'Job', 20, 6, '&nbsp;کۀ هغوئ د آسمانونو پورې هم اوچت شوى وى، او د هغوئ سرونه وريځو ته رسېدلى وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12345, 'Job 20:7', 'Job', 20, 7, '&nbsp;هغوئ به د خپلو متيازو په شان د تل دپاره ختم شى، چا چې هغوئ ليدلى وى نو هغوئ به ووائى چې څۀ شول؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12346, 'Job 20:8', 'Job', 20, 8, '&nbsp;هغوئ به د يو خوب په شان تېر شى او ورک به شى، هغوئ به د شپې د خوب په شان فنا شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12347, 'Job 20:9', 'Job', 20, 9, '&nbsp;کومو خلقو چې هغوئ ليدلى وى نو هغه به يې نور ونۀ ګورى، او چې چرته اوسېدل نو د هغه ځائ خلق به يې ياد نۀ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12348, 'Job 20:10', 'Job', 20, 10, '&nbsp;د هغوئ د اولاد نه به هغه مال دولت واپس لاړ شى، چې کوم يې د غريبانانو نه اخستے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12349, 'Job 20:11', 'Job', 20, 11, '&nbsp;هغوئ به په ځوانۍ کښې مړۀ شى او په خاورو کښې به ښخ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12350, 'Job 20:12', 'Job', 20, 12, '&nbsp;په بدعملۍ کښې خوند وى، او د دې خوند تر ډېر وخته پورې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12351, 'Job 20:13', 'Job', 20, 13, '&nbsp;او د خوږ څيز په شان يې په خولۀ کښې د ډېر وخت پورې ساتى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12352, 'Job 20:14', 'Job', 20, 14, '&nbsp;خو ناګهانه د هغوئ خوراک په خېټه کښې تريخ شى، او د دې نه دننه زهر جوړ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12353, 'Job 20:15', 'Job', 20, 15, '&nbsp;هغوئ مال دولت تېر کړى خو بيا يې اولټۍ کړى، خُدائ پاک د هغوئ دولت د هغوئ د خېټې نه واپس راوغورزوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12354, 'Job 20:16', 'Job', 20, 16, '&nbsp;هغوئ به د مارانو زهر وخورى، او زهرژن مار به هغوئ ووژنى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12355, 'Job 20:17', 'Job', 20, 17, '&nbsp;هغوئ به سيندونه ونۀ ګورى، هغه نِهرونه چې شات او پئ په کښې بهيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12356, 'Job 20:18', 'Job', 20, 18, '&nbsp;د هغوئ ناجائزه ګټه به د هغوئ نه واپس وځى، او په مال دولت باندې به خوشحالى ونۀ کړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12357, 'Job 20:19', 'Job', 20, 19, '&nbsp;ځکه چې هغوئ غريبانان وهلى دى او نهر يې پرېښى دى، او د هغوئ کورونه يې قبضه کړى دى کوم چې هغوئ نۀ دى جوړ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12358, 'Job 20:20', 'Job', 20, 20, '&nbsp;د هغوئ د حرص ختمېدل نشته، چې په څۀ خوشحاليږى نو د هغې نه به ورسره هيڅ پاتې نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12359, 'Job 20:21', 'Job', 20, 21, '&nbsp;هغوئ چې څۀ خورى نو د هغې نه هيڅ نۀ پاتې کيږى، نو په دې وجه د هغوئ مالدارى ختميږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12360, 'Job 20:22', 'Job', 20, 22, '&nbsp;کله چې هغوئ ښۀ کامياب وى، نو د غم چپې به په هغوئ باندې راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12361, 'Job 20:23', 'Job', 20, 23, '&nbsp;چې کله هغوئ خپلې خېټې ډکې کړى نو خُدائ پاک دې په هغوئ باندې سخت قهر راولى، او دا قهر دې په هغوئ لکه د ږلۍ راوريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12362, 'Job 20:24', 'Job', 20, 24, '&nbsp;هغوئ به د اوسپنې د وسلې نه تښتى، خو د زېړو په غشى به هغوئ ولګى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12363, 'Job 20:25', 'Job', 20, 25, '&nbsp;هغه غشے د هغوئ د ملا نه وويستلے شى، او دا غشے په وينه سور وى، يره به په هغوئ باندې راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12364, 'Job 20:26', 'Job', 20, 26, '&nbsp;د هغوئ خزانه به په تکه توره تيارۀ کښې پټه شى، يو داسې اور به هغوئ تباه کړى چې هيچا بل کړے نۀ وى، او د هغوئ په کور کښې پاتې هر څۀ به تباه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12365, 'Job 20:27', 'Job', 20, 27, '&nbsp;آسمانونه به د هغوئ ګناه ښکاره کړى، او زمکه به د هغوئ خِلاف ګواهى ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12366, 'Job 20:28', 'Job', 20, 28, '&nbsp;يو سېلاب به د هغۀ کور يوسى، د خُدائ پاک قهر به په هغوئ سېلاب راولى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12367, 'Job 20:29', 'Job', 20, 29, '&nbsp;دا د خُدائ پاک د طرف نه د بدعمله کسانو اَنجام دے، دا د هغوئ هغه ميراث دے چې د خُدائ پاک د طرف نه يې فېصله شوې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12368, 'Job 21:1', 'Job', 21, 1, '&nbsp;بيا ايُوب جواب ورکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12369, 'Job 21:2', 'Job', 21, 2, '&nbsp;”زما خبرې په غور سره واورئ، او دا دې تاسو له تسلى درکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12370, 'Job 21:3', 'Job', 21, 3, '&nbsp;ما پرېږدئ چې خبرې وکړم، او چې خبرې ختمې کړم نو بيا تاسو داړې چينګولے شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12371, 'Job 21:4', 'Job', 21, 4, '&nbsp;زما شکايت د خُدائ پاک نه دے د انسانانو نه نۀ دے. او د دې بې‌صبرۍ ما سره ښۀ سبب شته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12372, 'Job 21:5', 'Job', 21, 5, '&nbsp;ما ته وګورئ او حېران شئ، او ګوته په خولۀ کښې ونيسئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12373, 'Job 21:6', 'Job', 21, 6, '&nbsp;کله چې زۀ په دې سوچ وکړم نو خفه شم، او زما په بدن لړزان راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12374, 'Job 21:7', 'Job', 21, 7, '&nbsp;بدعمله خلق ولې ژوندى وى، او پوخ عُمر ته ورسيږى او طاقتور شى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12375, 'Job 21:8', 'Job', 21, 8, '&nbsp;د هغوئ بچى د هغوئ په وړاندې ودان شى، او د هغوئ نمسى د هغوئ په موجودګۍ کښې آباد شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12376, 'Job 21:9', 'Job', 21, 9, '&nbsp;د هغوئ کورونه د يرې نه بچ وى، او خُدائ پاک هغوئ له سزا نۀ ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12377, 'Job 21:10', 'Job', 21, 10, '&nbsp;د هغوئ غوَيے په مال کولو کښې هيڅکله نۀ ناکامه کيږى، د هغوئ غوا بچى راوړى او يو هم نۀ ضائع کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12378, 'Job 21:11', 'Job', 21, 11, '&nbsp;د هغوئ ماشومان د رَمو په شان ګرځى، او د هغوئ بچى د خوشحالۍ نه ګډيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12379, 'Job 21:12', 'Job', 21, 12, '&nbsp;هغوئ د تمبل او د رباب سره سندرې وائى، او د شپېلۍ د آواز سره خوشحالى کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12380, 'Job 21:13', 'Job', 21, 13, '&nbsp;هغوئ په مالدارۍ کښې وخت تېروى، او په خېر سره قبر ته ځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12381, 'Job 21:14', 'Job', 21, 14, '&nbsp;هغوئ خُدائ پاک ته وائى چې مونږ پرېږده. زمونږ زړۀ نۀ غواړى چې ستا تابعدارى وکړُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12382, 'Job 21:15', 'Job', 21, 15, '&nbsp;قادر خُدائ څوک دے، چې مونږ د هغۀ خِدمت وکړُو؟ او مونږ ته به څۀ فائده راورسيږى چې مونږ هغۀ ته سوال وکړُو؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12383, 'Job 21:16', 'Job', 21, 16, '&nbsp;خو هغوئ په خپل محنت سره نۀ دى مالداره شوى، د بدعمله کسانو مشوره ما ته منظوره نۀ ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12384, 'Job 21:17', 'Job', 21, 17, '&nbsp;د بدعمله خلقو ډيوه څو ځلې مړه کړے شوې وه؟ او څو ځلې په هغوئ باندې تباهى راغلې وه. خُدائ پاک څو ځلې په خپله غصه کښې سزا ورکوى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12385, 'Job 21:18', 'Job', 21, 18, '&nbsp;هغوئ څو ځلې د هوا په مخکښې د خسڼى په شان شول، او څو ځلې د بوسو په شان طوفان يوړل؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12386, 'Job 21:19', 'Job', 21, 19, '&nbsp;تۀ وائې چې، خُدائ پاک د هغوئ په وجه د هغوئ بچو له سزا ورکوى. نو دا سزا دې هم هغوئ له ورکړے شى، چې پته ورته ولګى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12387, 'Job 21:20', 'Job', 21, 20, '&nbsp;هغوئ دې په خپلو سترګو خپله تباهى وګورى، او د قادر خُدائ غصه دې تېره کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12388, 'Job 21:21', 'Job', 21, 21, '&nbsp;دا ځکه چې کله هغوئ مړۀ شى نو دا فکر به ورسره نۀ وى چې په خاندان يې څۀ کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12389, 'Job 21:22', 'Job', 21, 22, '&nbsp;څوک خُدائ پاک ته ښودنه کولے شى، هغه خُدائ پاک ته چې د غټو مرتبو لرونکو خلقو هم عدالت کوى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12390, 'Job 21:23', 'Job', 21, 23, '&nbsp;څوک چې ښۀ په مالدارۍ کښې مړ شى، هغه په آرام او حِفاظت کښې وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12391, 'Job 21:24', 'Job', 21, 24, '&nbsp;هغوئ ښۀ صحتمند وى، او ښۀ غټ او تکړه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12392, 'Job 21:25', 'Job', 21, 25, '&nbsp;بل کس په سخته غريبۍ کښې مړ شى، او هيڅکله يې ښۀ ورځ نۀ وى ليدلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12393, 'Job 21:26', 'Job', 21, 26, '&nbsp;هغوئ ټول يو شان مرى او په خاورو کښې ښخيږى، او هغوئ ټول د چينجو خوراک شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12394, 'Job 21:27', 'Job', 21, 27, '&nbsp;ګوره، ما ته ستا د سوچونو پته ده، او ما ته زما خِلاف ستا د منصوبو پته ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12395, 'Job 21:28', 'Job', 21, 28, '&nbsp;تۀ به ما ته د مالدارو او بدعمله خلقو په حقله ووائى، د چا کورونه چې د هغوئ د ګناهونو په وجه تباه شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12396, 'Job 21:29', 'Job', 21, 29, '&nbsp;خو تاسو هلته د موجودو خلقو نه تپوس ونۀ کړو، او د هغوئ ګواهى مو ونۀ منله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12397, 'Job 21:30', 'Job', 21, 30, '&nbsp;چې بدعمله کسان د مصيبت په وخت کښې خلاص شى، او د قهر په ورځ بچ کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12398, 'Job 21:31', 'Job', 21, 31, '&nbsp;څوک شته چې مخامخ ورباندې تنقيد وکړى، او چې د خپل عمل بدله ورکړى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12399, 'Job 21:32', 'Job', 21, 32, '&nbsp;کله چې هغوئ قبرستان ته يوړلے شى، نو خلق به د هغوئ د قبر خيال ساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12400, 'Job 21:33', 'Job', 21, 33, '&nbsp;زرګونه کسان د هغوئ په جنازه کښې شريک شى، او د عزت سره خاورو ته وسپارلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');